<?php
namespace App\Models;
use App\Enums\CommitteeElectionStatus;use Illuminate\Database\Eloquent\Model;
class CommitteeElection extends Model {protected $fillable=['public_uuid','formation_process_id','status','opens_at','closes_at','max_selections','electorate_count','candidate_count','opened_at','closed_at','scrutinized_at','results_validated_at','annulled_at','annulled_by','annulment_reason','result_integrity_hash','created_by','updated_by'];protected $casts=['status'=>CommitteeElectionStatus::class,'opens_at'=>'datetime','closes_at'=>'datetime','opened_at'=>'datetime','closed_at'=>'datetime','scrutinized_at'=>'datetime','results_validated_at'=>'datetime','annulled_at'=>'datetime'];public function formationProcess(){return $this->belongsTo(CommitteeFormationProcess::class);}public function candidates(){return $this->hasMany(CommitteeElectionCandidate::class,'election_id');}public function voters(){return $this->hasMany(CommitteeElectionVoter::class,'election_id');}public function ballots(){return $this->hasMany(CommitteeBallot::class,'election_id');}public function ties(){return $this->hasMany(CommitteeElectionTie::class,'election_id');}public function audits(){return $this->hasMany(CommitteeElectionAudit::class,'election_id');}public function finalFormation(){return $this->hasOne(CommitteeFormation::class,'election_id');}public function getRouteKeyName(){return 'public_uuid';}}
